argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$target='a6adf698764776856567239b07b0687e8ac89fa5';
$branch='agent/bridge-r42-live-control-plane-cutover-20261006';
$temp=Join-Path $env:TEMP ('r42-preflight-' + $target + '.ps1');
& git.exe -C $repo fetch origin $branch;
if($LASTEXITCODE -ne 0){ throw "git fetch failed: $LASTEXITCODE" }
$lines=@(& git.exe -C $repo show ($target + ':app/r42-cutover.ps1'));
if($LASTEXITCODE -ne 0 -or $lines.Count -eq 0){ throw "git show preflight script failed" }
[IO.File]::WriteAllText($temp,(($lines -join [Environment]::NewLine)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));
try{
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $temp -TargetSha $target -TargetBranch $branch -RepoPath $repo -PreflightOnly;
  if($LASTEXITCODE -ne 0){ throw "R42 preflight failed with exit $LASTEXITCODE" }
} finally {
  Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
}
